import datetime as dt, decimal, fractions
from humanize import precisedelta as p
for v in [decimal.Decimal(-3661), fractions.Fraction(-3661), -0.004, dt.timedelta(microseconds=-1), -3661.0, float('-inf') if False else -1e-9]:
    try: print(repr(v), repr(p(v)), repr(p(abs(v))))
    except Exception as e: print(repr(v), 'ERR', e)
try:
  import numpy as np; print(repr(p(np.int64(-3661))))
except Exception as e: print('np', e)
print(repr(p(dt.timedelta(seconds=-1), minimum_unit='minutes', format='%0.0f')), repr(p(dt.timedelta(seconds=1), minimum_unit='minutes', format='%0.0f')))
"

